import mathimport randomimport numpy as npimport ezdxffrom shapely.geometry import Polygonfrom shapely.affinity import rotate, translate# ===================== 基础参数 =====================AREA_WIDTH = 0.5AREA_HEIGHT = 0.5GRAIN_GROUPS = {    (0.06, 0.1): 9.83,    (0.04, 0.06): 17.73,    (0.02, 0.04): 20.90,    (0.01, 0.02): 17.68,    (0.01, 0.01): 13.85}MIN_EDGES = 6MAX_EDGES = 12# ===================== 核心调整参数（关键！） =====================MAX_MOVE_DISTANCE = 0.01  # 已有块石最大挪动距离MAX_ROTATE = 20  # 已有块石最大旋转角度ADJUST_TRIES = 6  # 每个重叠块尝试调整次数ALLOW_EXISTING_ROCK_MOVE = True  # 允许挪动已有块石（你要的功能）TARGET_STONE_RATIO = 40  # 目标含石量 %random.seed(42)np.random.seed(42)# ===================== 工具函数 =====================def generate_diameter(d_min, d_max):    return d_min + random.random() * (d_max - d_min)def generate_pos(diameter):    r = diameter / 2    x = r + random.random() * (AREA_WIDTH - 2 * r)    y = r + random.random() * (AREA_HEIGHT - 2 * r)    return x, ydef generate_poly(xc, yc, diameter, edges):    verts = []    angles = sorted([random.uniform(0, math.pi * 2) for _ in range(edges)])    radii = [diameter / 2 * random.uniform(0.75, 1.25) for _ in range(edges)]    for a, r in zip(angles, radii):        x = xc + r * math.cos(a)        y = yc + r * math.sin(a)        verts.append((x, y))    verts.append(verts[0])    return vertsdef poly_in_bounds(verts):    xs = [p[0] for p in verts]    ys = [p[1] for p in verts]    return min(xs) >= 0 and max(xs) <= AREA_WIDTH and min(ys) >= 0 and max(ys) <= AREA_HEIGHTdef check_overlap(poly_verts, rock_list):    p1 = Polygon(poly_verts)    for r in rock_list:        p2 = Polygon(r["vertices"])        if p1.intersects(p2):            return True    return Falsedef adjust_rock(rock, dx, dy, angle):    poly = Polygon(rock["vertices"][:-1])    poly = translate(poly, xoff=dx, yoff=dy)    poly = rotate(poly, angle, origin=poly.centroid)    verts = list(poly.exterior.coords)    if not poly_in_bounds(verts):        return None    verts.append(verts[0])    return vertsdef try_make_space(new_verts, existing_rocks):    for rock in existing_rocks:        orig_verts = rock["vertices"]        for _ in range(ADJUST_TRIES):            dx = random.uniform(-MAX_MOVE_DISTANCE, MAX_MOVE_DISTANCE)            dy = random.uniform(-MAX_MOVE_DISTANCE, MAX_MOVE_DISTANCE)            ang = random.uniform(-MAX_ROTATE, MAX_ROTATE)            adjusted = adjust_rock(rock, dx, dy, ang)            if not adjusted:                continue            rock["vertices"] = adjusted            if not check_overlap(new_verts, existing_rocks):                return True            rock["vertices"] = orig_verts    return Falsedef calc_area(verts):    return Polygon(verts).area# ===================== 主生成逻辑 =====================def generate_rocks():    all_rocks = []    total_area = AREA_WIDTH * AREA_HEIGHT    target_total = total_area * TARGET_STONE_RATIO / 100    group_sum = sum(GRAIN_GROUPS.values())    print(f"🎯 目标含石量：{TARGET_STONE_RATIO}%")    for (dmin, dmax), ratio in GRAIN_GROUPS.items():        target = target_total * (ratio / group_sum)        current = 0        attempts = 0        while current < target and attempts < 200000:            attempts += 1            dia = generate_diameter(dmin, dmax)            x, y = generate_pos(dia)            e = random.randint(MIN_EDGES, MAX_EDGES)            verts = generate_poly(x, y, dia, e)            if not poly_in_bounds(verts):                continue            # 检查重叠            if check_overlap(verts, all_rocks):                if ALLOW_EXISTING_ROCK_MOVE:                    ok = try_make_space(verts, all_rocks)                    if not ok:                        continue                else:                    continue            # 最终校验：绝对无重叠            if check_overlap(verts, all_rocks):                continue            area = calc_area(verts)            if current + area > target * 1.03:                continue            current += area            all_rocks.append({                "group": f"{dmin}-{dmax}",                "vertices": verts,                "area": area            })        print(f"✅ 粒组 {dmin}-{dmax} 完成 | 面积占比：{current / total_area * 100:.2f}%")    final_ratio = sum(r["area"] for r in all_rocks) / total_area * 100    print(f"\n🎉 最终总含石量：{final_ratio:.2f}%")    print(f"🪨 总块石数量：{len(all_rocks)}")    return all_rocks# ===================== DXF导出 =====================def export_dxf(rocks, filename="HIGH_STONE_RATIO.dxf"):    doc = ezdxf.new("R2010")    msp = doc.modelspace()    colors = {"0.06-0.1": 1, "0.04-0.06": 2, "0.02-0.04": 3, "0.01-0.02": 4, "0.01-0.01": 5}    for g, c in colors.items():        doc.layers.new(name=g, color=c)    for r in rocks:        msp.add_lwpolyline(r["vertices"], closed=True, layer=r["group"], color=colors[r["group"]])    doc.saveas(filename)    print(f"\n💾 DXF已保存：{filename}")# ===================== 运行 =====================if __name__ == "__main__":    rocks = generate_rocks()    export_dxf(rocks)